            <Field.Validity>{(s) => <span data-testid="v">{typeof s.initialValue}</span>}</Field.Validity>
          </Field.Root>
          <button type="submit">go</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('go'));
    console.log(label, 'submit validate arg', typeof validate.mock.lastCall?.[0], JSON.stringify(validate.mock.lastCall?.[0]), 'initialValue type', screen.getByTestId('v').textContent);
  });

